     <h3>My Text</h3>
     <input matInput type="text" [(ngModel)]="myText.value">
   </div>

   <mat-multiselectlist
     [multiple]="true"
     placeholder="Select items"
     [(ngModel)]="selectedItems"
   >
     <button *ngFor="let item of myListItems; let i = index" mat-list-item (click)="addListItem()">
       {{item}}
     </button>
   </mat-multiselectlist>

   <button (click)="removeSelected()">Remove Selected</button>
