    <!-- Container for the background image -->
    <div id="backgroundImage"></div>

    <script>
        // Function to fetch and set the background image
        function setBackgroundImage() {
            const url = window.getComputedStyle(document.documentElement).getPropertyValue('--bg-image');
            if (url) {
                document.getElementById('backgroundImage').style.backgroundImage = `url(${url})`;
            } else {
                alert("No computer background image found.");
            }
        }

        // Set the default background image as the fallback
        document.body.style.setProperty('--bg-image', 'https://example.com/default_background.jpg');

        // Attach event listener to the button
